-- Nexmark q20 on flink, BLACKHOLE sink variant. Expand bid with auction: bid
-- joined to auction on the auction id.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (
  `auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `channel` STRING, `url` STRING, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-bid',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q20bh-bid',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE auction (
  `id` BIGINT, `itemname` STRING, `initialbid` BIGINT, `reserve` BIGINT, `expires` BIGINT, `seller` BIGINT, `category` BIGINT, `datetime` BIGINT,
  ts AS TO_TIMESTAMP_LTZ(`datetime`, 3),
  WATERMARK FOR ts AS ts - INTERVAL '4' SECOND
) WITH (
  'connector' = 'kafka',
  'topic' = 'nx-auction',
  'properties.bootstrap.servers' = 'kafka:29092',
  'properties.group.id' = 'flink-q20bh-auction',
  'scan.startup.mode' = 'earliest-offset',
  'format' = 'json',
  'json.ignore-parse-errors' = 'false'
);
CREATE TABLE sink_q20 (`auction` BIGINT, `bidder` BIGINT, `price` BIGINT, `itemname` STRING) WITH ('connector' = 'blackhole');
INSERT INTO sink_q20
SELECT B.auction, B.bidder, B.price, A.itemname FROM bid AS B JOIN auction AS A ON B.auction = A.id;
